import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");
        String format = req.getParameter("format");

        // Validate report type against allowed list
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date validation
        if (!isValidDate(startDate) || !isValidDate(endDate)) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String query = buildReportQuery(reportType, startDate, endDate, department, sortCol);
            log.info("Executing report query for type=" + reportType + " dept=" + department);

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    row.put(meta.getColumnLabel(i), rs.getObject(i));
                }
                results.put(row);
            }
            out.print(results.toString());
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildReportQuery(String type, String start, String end,
                                     String department, String sortCol) {
        String baseTable = getTableForReport(type);
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM ").append(baseTable);
        sb.append(" WHERE created_at BETWEEN '").append(start).append("' AND '").append(end).append("'");

        if (department != null && !department.isEmpty()) {
            sb.append(" AND department = '").append(department).append("'");
        }

        if (sortCol != null && !sortCol.isEmpty()) {
            sb.append(" ORDER BY ").append(sortCol);
        }

        return sb.toString();
    }

    private String getTableForReport(String type) {
        switch (type) {
            case "sales": return "monthly_sales";
            case "inventory": return "warehouse_inventory";
            case "hr": return "employee_records";
            default: return "monthly_sales";
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("sales") || type.equals("inventory") || type.equals("hr"));
    }

    private boolean isValidDate(String date) {
        if (date == null) return false;
        return date.matches("\\d{4}-\\d{2}-\\d{2}");
    }
}
